library(shiny)
library(jsonlite)
library(readxl)

source("R/ingest.R")
source("R/templates.R")


if (dir.exists("vendor")) addResourcePath("vendor", "vendor")

#--------------------------------------------------------------------- ui ------
ui <- fluidPage(
  title = "BCSSE Report Generator",
  lang = "en",
  tags$head(
    tags$script(src = "typst-bridge.js", type = "module"),
    tags$style(HTML("
      body { max-width: 960px; margin: 0 auto; padding: 20px 12px 40px;
             font-family: system-ui, sans-serif; color: #1a1a1a; }
      h1 { font-size: 26px; margin-bottom: 4px; }
      h2 { font-size: 20px; font-weight: 600; margin: 0 0 6px; }
      .app-header { display: flex; align-items: center; gap: 14px; margin-bottom: 4px; }
      .app-header h1 { margin: 0; }
      .lede { color: #4d4d4d; margin-bottom: 18px; line-height: 1.5; }
      .panel { border: 1px solid #d8d8d8; border-radius: 6px;
               padding: 11px 12px; margin-bottom: 11px; }
      .problem { border-left: 3px solid #b3261e; background: #fdf5f4; }
      .ready { border-left: 3px solid #1f4e5f; background: #f4f8f9; }
      #status { font-variant-numeric: tabular-nums; color: #4d4d4d; }
      .filters-help { color: #4d4d4d; font-size: 15px; margin-bottom: 14px; }
      .btn-file:focus-within { outline: 3px solid #1f4e5f; outline-offset: 2px; }
      .form-control { border-color: #767676; }
      .form-control::placeholder { color: #595959; opacity: 1; }
      .generate-row { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; }
      .generate-row .form-group { margin-bottom: 0; }    
    "))
  ),
  
  div(class = "app-header",
      tags$img(src = "BCSSE_clear_small.png", alt = "BCSSE logo", height = 56),
      h1("BCSSE Report Generator")),
  
  p(class = "lede",
    "Export your dashboard as an Excel file; drop it below to get an advising report for each student. Your data stays on your computer and is never uploaded to the web."),
  
      div(class = "panel",
          fileInput("file", "Choose your dashboard export (.xlsx)", accept = ".xlsx",
                    width = "100%", buttonLabel = "Browse", placeholder = "No file chosen")),
      
      div(class = "panel",
      radioButtons("rtype", "Report type",
                   choices = setNames(names(TEMPLATES),
                                      vapply(TEMPLATES, `[[`, "", "label")),
                   selected = names(TEMPLATES)[1])),
      
  #Select Filters - organized in three columns and three rows
  tags$section(class = "panel", `aria-labelledby` = "filters-heading",
               h2(id = "filters-heading", "Optional Filters"),
               p(class = "filters-help",
                 "Leave a box blank, or a list set to \"All\", to include every student."),
               
               fluidRow(
                 column(4, tagAppendAttributes(textInput("LN17", "Last name", width = "100%"),
                                               list = "LN17_list", autocomplete = "off", .cssSelector = "input")),
                 column(4, tagAppendAttributes(textInput("bstudidC2", "Student ID", width = "100%"),
                                               list = "bstudid_list", autocomplete = "off", .cssSelector = "input")),
                 column(4, tagAppendAttributes(textInput("Advisor", "Advisor", width = "100%"),
                                               list = "Advisor_list", autocomplete = "off", .cssSelector = "input"))
                 ),
               uiOutput("suggestions"),
               
               fluidRow(
                 column(4, selectInput("LN_init", "First letter of last name",
                                       choices = c("All", LETTERS), selected = "All",
                                       selectize = FALSE, width = "100%")),
                 column(4, selectInput("cmajor", "Student major",
                                       choices = "All", selected = "All",
                                       selectize = FALSE, width = "100%")),
                 column(4, selectInput("first_gen", "First-generation status",
                                       choices = "All", selected = "All",
                                       selectize = FALSE, width = "100%"))
                 ),
               fluidRow(
                 column(4, selectInput("Group1", "Group 1",
                                       choices = "All", selected = "All",
                                       selectize = FALSE, width = "100%")),
                 column(4, selectInput("Group2", "Group 2",
                                       choices = "All", selected = "All",
                                       selectize = FALSE, width = "100%")),
                 column(4, div(style = "padding-top: 25px;",
                               actionButton("clear_filters", "Reset all filters", width = "100%")))
                 )
               ),
  uiOutput("check"),
      
  div(class = "panel",
      div(class = "generate-row",
          radioButtons("fname", "Name each PDF by",
                       choices = c("Student ID (e.g., 1234567.pdf)" = "id",
                                   "Student name(e.g., Jane-Smith.pdf)" = "name"),
                       selected = "id", inline = TRUE),
          
          actionButton("go", "Generate Reports", class = "btn-primary")),
      tags$p(id = "status", role = "status", `aria-live` = "polite",
             style = "margin-top: 8px;"),
      uiOutput("result"))
)


#------------------------------------------------------------------ server -----
server <- function(input, output, session) {

  upload <- reactive({
    req(input$file)
    read_upload(input$file$datapath)
  })

  result_msg <- reactiveVal(NULL)
  output$result <- renderUI({
    m <- result_msg()
    if (is.null(m)) return(NULL)
    if (m$ok) div(class = "panel ready", m$text)
    else div(class = "panel problem", role = "alert", strong("Problem: "), m$text)
  })
  
  observeEvent(upload(), {
    u <- upload()
    if (!u$ok) return()
    for (col in names(FILTER_DROPDOWNS)) {
      updateSelectInput(session, FILTER_DROPDOWNS[[col]],
                        choices = filter_choices(u$data, col),
                        selected = "All")
    }
  })
  
  filtered <- reactive({
    u <- upload()
    if (!u$ok) return(NULL)
    f <- filter_by_type(u$data, input$rtype)
    apply_filters(f, list(
      LN17 = input$LN17, bstudid = input$bstudid, Advisor = input$Advisor,
      LN_init = input$LN_init, cmajor = input$cmajor,
      first_gen = input$first_gen, Group1 = input$Group1, Group2 = input$Group2
    ))
  })
  
  #Prevent screen reader from announcing student count after Every. Single. Keystroke.
  filtered_d <- debounce(filtered, 500)

  output$check <- renderUI({
    u <- upload()
    if (!u$ok) return(div(class = "panel problem", strong("Problem: "), u$error))

    f <- filtered_d()
    if (f$n_kept == 0) {
      div(class = "panel problem", strong("Problem: "), tally_message(f, input$rtype))
    } else {
      div(class = "panel ready", tally_message(f, input$rtype))
    }
  })
  
  #Action for clear filters button
  observeEvent(input$clear_filters, {
    for (id in c("LN17", "bstudid", "Advisor")) updateTextInput(session, id, value = "")
    for (id in c("LN_init", unname(FILTER_DROPDOWNS))) updateSelectInput(session, id, selected = "All")
  })
  
  output$suggestions <- renderUI({
    u <- upload()
    if (!u$ok) return(NULL)
    df <- filter_by_type(u$data, input$rtype)$kept
    opts <- function(id, col) {
      v <- if (col %in% names(df)) sort(unique(df[[col]][nzchar(df[[col]])])) else character(0)
      tags$datalist(id = id, lapply(v, function(x) tags$option(value = x)))
    }
    tagList(opts("LN17_list", "LN17"),
            opts("bstudid_list", "bstudidC2"),
            opts("Advisor_list", "Advisor"))
  })

  observeEvent(input$go, {
    result_msg(NULL)
    u <- upload()
    if (!u$ok) return(result_msg(list(ok = FALSE, text = u$error)))
    
    f <- filtered()
    if (f$n_kept == 0) {
      return(result_msg(list(ok = FALSE, text = tally_message(f, input$rtype))))
    }
    
    tpl <- TEMPLATES[[input$rtype]]
    mode <- if (identical(input$fname, "id")) "id" else "name"
    msg <- build_compile_message(f$kept, tpl, filename_mode = mode)
    session$sendCustomMessage("compile_typst", msg)
    })

  observeEvent(input$compile_result, {
    res <- input$compile_result
    if (isTRUE(res$ok)) {
      msg <- sprintf("Generated %d report(s).", res$n)
      if (res$failed > 0) msg <- paste(msg, sprintf("%d failed; see errors.txt in the zip.", res$failed))
      result_msg(list(ok = TRUE, text = msg))
    } else {
      result_msg(list(ok = FALSE, text = paste("Generation failed:", res$error)))
    }
  })
}

shinyApp(ui, server)

REQUIRED_COLS <- c("Stype", "FN17", "LN17", "bstudidC2")

#Reads an uploaded dashboard export.
#Everything is read as character on purpose to avoid messing up IDs
read_upload <- function(path) {
  if (!file.exists(path)) {
    return(list(ok = FALSE, data = NULL, error = "The file could not be read."))
  }

  df <- tryCatch(
    read_excel(path, col_types = "text"),
    error = function(e) NULL
  )

  if (is.null(df) || ncol(df) == 0) {
    return(list(ok = FALSE, data = NULL,
                error = "The file could not be read as xlsx."))
  }

  missing <- setdiff(REQUIRED_COLS, names(df))
  if (length(missing) > 0) {
    return(list(ok = FALSE, data = NULL, error = sprintf(
      "This file is missing required column(s): %s.",
      paste(missing, collapse = ", ")
    )))
  }

  list(ok = TRUE, data = df, error = NULL)
}

// ===============================================
